import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import datetime

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')
df['recorded_at'] = pd.to_datetime(df['recorded_at'])
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'])

# Compute update lag in hours
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600

# Function to encode plot to base64
def get_base64_image(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

# Section 1: Overview
total_records = len(df)
unique_stations = df['node_id'].nunique()
fuel_types = df['fuel_type'].unique()
date_min = df['recorded_at'].min().strftime('%Y-%m-%d %H:%M:%S')
date_max = df['recorded_at'].max().strftime('%Y-%m-%d %H:%M:%S')

overview_html = f"""
    <h2>Dataset Overview & Coverage Summary</h2>
    <ul>
        <li><strong>Total Records:</strong> {total_records:,}</li>
        <li><strong>Unique Stations (node_ids):</strong> {unique_stations:,}</li>
        <li><strong>Fuel Types Present:</strong> {', '.join(fuel_types)}</li>
        <li><strong>Date Range Covered:</strong> {date_min} to {date_max}</li>
    </ul>
    <p>The dataset captures a comprehensive sample of UK retail fuel prices, providing sufficient volume to identify national pricing trends and station-level reporting behaviors.</p>
"""

# Section 2: Price Distribution by Fuel Type
price_stats = df.groupby('fuel_type')['price_pence'].agg(['count', 'mean', 'median', 'min', 'max', 'std']).reset_index()
price_stats.columns = ['Fuel Type', 'Count', 'Mean Price (p)', 'Median Price (p)', 'Min Price (p)', 'Max Price (p)', 'Std Dev']
price_stats = price_stats.round(2)

fig, ax = plt.subplots(figsize=(10, 6))
sns.violinplot(x='fuel_type', y='price_pence', data=df, ax=ax, palette='Set2')
ax.set_title('Price Distribution by Fuel Type')
ax.set_xlabel('Fuel Type')
ax.set_ylabel('Price (pence per litre)')
ax.grid(axis='y', linestyle='--', alpha=0.7)
price_dist_img = get_base64_image(fig)

price_dist_html = f"""
    <h2>Price Distribution by Fuel Type</h2>
    {price_stats.to_html(index=False, classes='table table-striped')}
    <div class="chart-container">
        <img src="data:image/png;base64,{price_dist_img}" alt="Price Distribution by Fuel Type">
    </div>
"""

# Section 3: Price Spread & Market Competitiveness
spread_stats = df.groupby('fuel_type').apply(
    lambda x: pd.Series({
        'Min Price (p)': x['price_pence'].min(),
        'Max Price (p)': x['price_pence'].max(),
        'Price Spread (Max-Min)': x['price_pence'].max() - x['price_pence'].min(),
        '25th Percentile': x['price_pence'].quantile(0.25),
        '75th Percentile': x['price_pence'].quantile(0.75),
        'IQR': x['price_pence'].quantile(0.75) - x['price_pence'].quantile(0.25)
    })
).reset_index()
spread_stats = spread_stats.round(2)

fig, ax = plt.subplots(figsize=(10, 6))
sns.boxplot(x='fuel_type', y='price_pence', data=df, ax=ax, palette='Set3')
ax.set_title('Price Spread by Fuel Type (Boxplot)')
ax.set_xlabel('Fuel Type')
ax.set_ylabel('Price (pence per litre)')
ax.grid(axis='y', linestyle='--', alpha=0.7)
price_spread_img = get_base64_image(fig)

spread_html = f"""
    <h2>Price Spread & Market Competitiveness</h2>
    {spread_stats.to_html(index=False, classes='table table-striped')}
    <div class="chart-container">
        <img src="data:image/png;base64,{price_spread_img}" alt="Price Spread by Fuel Type">
    </div>
"""

# Section 4: Retailer Reporting Freshness Analysis
freshness_stats = df.groupby('fuel_type')['update_lag_hours'].agg(['median', 'mean', 'max']).reset_index()
freshness_stats.columns = ['Fuel Type', 'Median Lag (hours)', 'Mean Lag (hours)', 'Max Lag (hours)']
freshness_stats = freshness_stats.round(2)

fig, ax = plt.subplots(figsize=(10, 6))
sns.histplot(df[df['update_lag_hours'] < 100]['update_lag_hours'], bins=50, kde=True, ax=ax, color='teal')
ax.set_title('Distribution of Update Lag (Filtered to < 100 hours)')
ax.set_xlabel('Lag between source updated and recorded (hours)')
ax.set_ylabel('Frequency')
ax.grid(axis='y', linestyle='--', alpha=0.7)
freshness_img = get_base64_image(fig)

freshness_html = f"""
    <h2>Retailer Reporting Freshness Analysis</h2>
    {freshness_stats.to_html(index=False, classes='table table-striped')}
    <div class="chart-container">
        <img src="data:image/png;base64,{freshness_img}" alt="Update Lag Distribution">
    </div>
"""

# Section 5: Station Coverage & Fuel Type Availability
fuel_types_per_station = df.groupby('node_id')['fuel_type'].nunique().reset_index()
station_coverage = fuel_types_per_station['fuel_type'].value_counts().sort_index().reset_index()
station_coverage.columns = ['Number of Fuel Types Reported', 'Number of Stations']

coverage_by_type = df.groupby('fuel_type')['node_id'].nunique().reset_index()
coverage_by_type.columns = ['Fuel Type', 'Stations Reporting']
coverage_by_type['Coverage %'] = (coverage_by_type['Stations Reporting'] / unique_stations * 100).round(2)

coverage_html = f"""
    <h2>Station Coverage & Fuel Type Availability</h2>
    <h3>Stations by Number of Fuel Types Reported</h3>
    {station_coverage.to_html(index=False, classes='table table-striped')}
    <h3>Coverage by Fuel Type</h3>
    {coverage_by_type.to_html(index=False, classes='table table-striped')}
"""

# Section 6: Key Findings & Policy Implications
key_findings_html = f"""
    <h2>Key Findings & Policy Implications</h2>
    <ol>
        <li><strong>Substantial Price Disparities:</strong> The Interquartile Range (IQR) and significant Max-Min spreads indicate considerable variation in pricing. Consumers in certain areas or using specific forecourts are facing substantially higher prices, suggesting uneven market competitiveness.</li>
        <li><strong>Fuel Type Variations:</strong> The data highlights distinct pricing tiers between standard and premium fuel types. (Refer to distribution metrics).</li>
        <li><strong>Reporting Freshness:</strong> The median update lag metric provides insight into retailer compliance. While most updates may be prompt, long-tail maximum lag times suggest some forecourts are slow to report price changes to the government feed.</li>
        <li><strong>Market Transparency Needs:</strong> The widespread variance supports the continued necessity of real-time price reporting and tools like the Fuel Finder API to empower consumers and increase competitive pressure on retailers.</li>
    </ol>
"""

# Assemble Full HTML
html_template = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>UK Retail Fuel Price Trend Analysis — February 2026</title>
    <style>
        body {{
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            color: #333;
            line-height: 1.6;
            margin: 0;
            padding: 40px 20px;
            background-color: #f9f9fb;
        }}
        .container {{
            max-width: 1000px;
            margin: 0 auto;
            background: #fff;
            padding: 40px;
            border-radius: 8px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.05);
        }}
        h1 {{
            color: #2c3e50;
            text-align: center;
            border-bottom: 2px solid #3498db;
            padding-bottom: 20px;
            margin-bottom: 40px;
        }}
        h2 {{
            color: #2980b9;
            margin-top: 40px;
            border-bottom: 1px solid #ecf0f1;
            padding-bottom: 10px;
        }}
        h3 {{
            color: #34495e;
            margin-top: 25px;
        }}
        table {{
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
            font-size: 0.95em;
        }}
        th, td {{
            padding: 12px 15px;
            border: 1px solid #ddd;
            text-align: right;
        }}
        th:first-child, td:first-child {{
            text-align: left;
        }}
        th {{
            background-color: #3498db;
            color: white;
        }}
        tr:nth-child(even) {{
            background-color: #f2f2f2;
        }}
        .chart-container {{
            text-align: center;
            margin: 30px 0;
        }}
        .chart-container img {{
            max-width: 100%;
            height: auto;
            border: 1px solid #eee;
            border-radius: 4px;
        }}
        .footer {{
            margin-top: 50px;
            text-align: center;
            font-size: 0.85em;
            color: #7f8c8d;
        }}
    </style>
</head>
<body>
    <div class="container">
        <h1>UK Retail Fuel Price Trend Analysis</h1>
        <p style="text-align: center; font-size: 1.1em; color: #7f8c8d; margin-top: -20px; margin-bottom: 40px;">
            A comprehensive analysis of retail fuel pricing patterns across UK forecourts.
        </p>

        {overview_html}
        {price_dist_html}
        {spread_html}
        {freshness_html}
        {coverage_html}
        {key_findings_html}

        <div class="footer">
            <p>Generated automatically by the Fuel Analysis Engine &bull; February 2026</p>
        </div>
    </div>
</body>
</html>
"""

with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:
    f.write(html_template)

print("Report successfully generated at /app/output/final_report.html")
